import 'server-only';

/** Default link-preview image (1200×630), generated by scripts/og-image.cjs from the logo. */
export const DEFAULT_OG_IMAGE = '/images/og-image.jpg';

/** Open Graph image entry; the default image carries its size so previews render at full width. */
export function ogImage(url, alt) {
  const src = url || DEFAULT_OG_IMAGE;
  return src === DEFAULT_OG_IMAGE ? { url: src, width: 1200, height: 630, alt } : { url: src, alt };
}

/**
 * Absolute origin used to turn relative image paths into full URLs (WhatsApp,
 * Facebook and X ignore relative og:image values). Static pages have no request
 * host, so it comes from the "Public site URL" setting when that is a real
 * domain, else from NEXT_PUBLIC_SITE_URL. Read at build time: rebuild after changing either.
 */
export function siteOrigin(configured) {
  for (const value of [configured, process.env.NEXT_PUBLIC_SITE_URL]) {
    try {
      const url = new URL(value);
      if (!/(^|\.)example\.com$/i.test(url.hostname)) return url;
    } catch {
      // not set or not a URL
    }
  }
  return undefined;
}

/** Shared Open Graph + Twitter card fields. */
export function socialMeta({ title, description, image, siteName, lang }) {
  return {
    openGraph: {
      type: 'website',
      siteName,
      title,
      description,
      locale: lang === 'en' ? 'en_US' : 'ar_EG',
      images: [image],
    },
    twitter: { card: 'summary_large_image', title, description, images: [image.url] },
  };
}
